package com.xdownload.mobile;import org.junit.Test;import static org.junit.Assert.*;public class QuickLinkTest{@Test public void acceptsSingleAuthorizedWebUrl(){assertEquals("https://example.org/video.mp4?a=1",QuickLink.parse(" https://example.org/video.mp4?a=1 ",false));assertEquals("example.org",QuickLink.host("https://example.org/video.mp4"));assertEquals("",QuickLink.parse("http://example.org/file",false));assertEquals("http://example.org/file",QuickLink.parse("http://example.org/file",true));}@Test public void rejectsCredentialsSecretsAndNonLinks(){for(String text:new String[]{"password","https://user:secret@example.org/","file:///etc/passwd","javascript:alert(1)","https://example.org/a https://example.org/b","https://example.org:99999/a","https://example.org:0/a","https://example.org/a\nsecret"})assertEquals("",QuickLink.parse(text,true));assertEquals("",QuickLink.parse(null,false));} @Test public void sharedCaptionSingleLinkOnly(){assertEquals("https://example.org/media",QuickLink.shared("Watch this https://example.org/media",false));assertEquals("",QuickLink.shared("https://a.org/one https://b.org/two",false));assertEquals("",QuickLink.shared("https://user:secret@example.org/media",false));}}